gold.schema_ddl:
CREATE TABLE clienti (
    id SERIAL PRIMARY KEY,
    nome TEXT NOT NULL,
    codice_fiscale TEXT NOT NULL UNIQUE,
    email TEXT
);

CREATE TABLE ordini (
    id SERIAL PRIMARY KEY,
    cliente_id INT NOT NULL REFERENCES clienti(id),
    qty INT NOT NULL CHECK (qty > 0),
    data_ordine DATE NOT NULL DEFAULT CURRENT_DATE,
    importo_totale NUMERIC(10,2) CHECK (importo_totale >= 0)
);

CREATE TABLE magazzini (
    id SERIAL PRIMARY KEY,
    nome TEXT NOT NULL,
    indirizzo TEXT,
    capacita_massima_kg DECIMAL(10, 2) CHECK (capacita_massima_kg >= 0)
);

CREATE TABLE corsie (
    id SERIAL PRIMARY KEY,
    magazzino_id INT NOT NULL REFERENCES magazzini(id),
    nome TEXT NOT NULL,
    lunghezza_metri DECIMAL(10, 2) CHECK (lunghezza_metri > 0)
);

CREATE TABLE colli (
    id SERIAL PRIMARY KEY,
    corsia_id INT NOT NULL REFERENCES corsie(id),
    peso_kg DECIMAL(10, 2) CHECK (peso_kg >= 0),
    descrizione TEXT,
    data_ingresso TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE citta (
    id SERIAL PRIMARY KEY,
    nome TEXT NOT NULL,
    provincia_id INT REFERENCES citta(id)
);

CREATE TABLE spedizioni (
    id SERIAL PRIMARY KEY,
    citta_origine_id INT NOT NULL REFERENCES citta(id),
    citta_destinazione_id INT NOT NULL REFERENCES citta(id),
    peso_kg NUMERIC(10,2) CHECK (peso_kg >= 0),
    data_spedizione DATE NOT NULL,
    stato TEXT CHECK (stato IN ('in_transito', 'consegnata', 'annullata'))
);

CREATE TABLE conti (
    id INT PRIMARY KEY,
    nome_conto TEXT NOT NULL,
    tipo_conto TEXT NOT NULL CHECK (tipo_conto IN ('attivo', 'passivo', 'patrimonio_netto', 'ricavo', 'costo'))
);

CREATE TABLE transazioni (
    id INT PRIMARY KEY,
    conto_id INT NOT NULL REFERENCES conti(id),
    data_transazione DATE NOT NULL,
    descrizione TEXT,
    importo_totale NUMERIC(12,2) CHECK (importo_totale >= 0)
);

CREATE TABLE voci_transazione (
    id INT PRIMARY KEY,
    transazione_id INT NOT NULL REFERENCES transazioni(id),
    descrizione TEXT,
    dare NUMERIC(12,2) CHECK (dare >= 0),
    avere NUMERIC(12,2) CHECK (avere >= 0)
);

CREATE TABLE corrieri (
    id SERIAL PRIMARY KEY,
    nome TEXT NOT NULL,
    telefono TEXT,
    citta TEXT NOT NULL
);

CREATE TABLE indirizzi (
    id SERIAL PRIMARY KEY,
    via TEXT NOT NULL,
    citta TEXT NOT NULL,
    cap TEXT NOT NULL
);

CREATE TABLE pacchi (
    id SERIAL PRIMARY KEY,
    corriere_id INT NOT NULL REFERENCES corrieri(id),
    indirizzo_id INT NOT NULL REFERENCES indirizzi(id),
    peso NUMERIC(8,2) CHECK (peso > 0),
    descrizione TEXT,
    cap TEXT NOT NULL,
    citta TEXT NOT NULL
);

CREATE TABLE stati_pacco (
    id SERIAL PRIMARY KEY,
    pacchetto_id INT NOT NULL REFERENCES pacchi(id),
    stato TEXT NOT NULL,
    data_aggiornamento TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE tipi_pacco (
    id SERIAL PRIMARY KEY,
    pacchetto_id INT NOT NULL REFERENCES pacchi(id),
    tipo TEXT NOT NULL,
    peso_lordo NUMERIC(8,2) CHECK (peso_lordo >= 0)
);

CREATE TABLE prodotti (
    id INT PRIMARY KEY,
    nome TEXT NOT NULL,
    numero INT NOT NULL CHECK (numero >= 0),
    prezzo_unitario NUMERIC(10,2) CHECK (prezzo_unitario >= 0)
);

CREATE TABLE vendite (
    id INT PRIMARY KEY,
    prodotto_id INT NOT NULL REFERENCES prodotti(id),
    quantita INT NOT NULL CHECK (quantita > 0),
    data_vendita DATE NOT NULL
);

CREATE TABLE magazzino (
    id SERIAL PRIMARY KEY,
    nome TEXT NOT NULL,
    citta TEXT NOT NULL,
    stato TEXT NOT NULL CHECK (stato <> '')
);

CREATE TABLE ordine (
    id SERIAL PRIMARY KEY,
    data_ordine DATE NOT NULL DEFAULT CURRENT_DATE,
    stato TEXT NOT NULL CHECK (stato IN ('in_elaborazione', 'in_transito', 'completato', 'annullato'))
);

CREATE TABLE magazzino_ordine (
    magazzino_id INT NOT NULL REFERENCES magazzino(id),
    ordine_id INT NOT NULL REFERENCES ordine(id),
    quantita INT CHECK (quantita > 0),
    PRIMARY KEY (magazzino_id, ordine_id)
);

CREATE TABLE clienti (
    id INT PRIMARY KEY,
    nome TEXT NOT NULL,
    codice_fiscale TEXT NOT NULL UNIQUE
);

